# 🕵️ كاشف التجسس والاتصالات المشبوهة
# ملاحظة: هذا الكود يفحص الاتصالات في بيئة Termux.
import subprocess
import os
import time

def check_network_connections():
    print('--- [1] فحص الاتصالات الشبكية النشطة ---')
    try:
        result = subprocess.run(['netstat', '-tunap'], capture_output=True, text=True)
        lines = result.stdout.split('\n')
        active = [line for line in lines if 'ESTABLISHED' in line or 'LISTEN' in line]
        if active:
            for line in active:
                print(line)
        else:
            print('لا توجد اتصالات نشطة حالياً.')
    except Exception as e:
        print(f'خطأ في قراءة الشبكة: {e}')

def check_suspicious_processes():
    print('\n--- [2] فحص العمليات (البرامج) اللي بتستهلك موارد ---')
    try:
        result = subprocess.run(['ps', '-eo', 'pid,comm,%cpu,%mem', '--sort=-%cpu'], capture_output=True, text=True)
        lines = result.stdout.split('\n')[:10]
        for line in lines:
            print(line)
    except Exception as e:
        print(f'خطأ في قراءة العمليات: {e}')

def monitor_traffic():
    print('\n--- [3] مراقبة حركة البيانات ---')
    print('جاري مراقبة استهلاك البيانات (اضغط Ctrl+C للإيقاف)...')
    try:
        subprocess.run(['ifstat', '-i', 'wlan0', '1', '5'])
    except:
        print('أداة ifstat غير مثبتة. نزل المكتبة: pkg install ifstat')

if __name__ == '__main__':
    print('🚀 بدء فحص الجهاز للتأكد من عدم وجود تجسس...')
    check_network_connections()
    check_suspicious_processes()
    print('\n💡 نصيحة: لو لقيت اتصال مشبوه، أو تطبيق غريب شغال، يبقى ممكن يكون فيه تجسس.')
    print('للأسف مفيش أداة واحدة بتمنع التجسس، الحماية الحقيقية هي إنك متدوسش على لينكات ومتنزلش تطبيقات من برا جوجل بلاي.')
